insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_82_v1'
from (values
('127.674.d.1.A',3,'Which source would give a student the clearest picture of what a software intern does each week?','["A company''s internship posting listing responsibilities", "A random social media meme", "A cafeteria menu", "A weather forecast"]'::jsonb,0,'Postings describe the duties and tasks of a role.','original'),
('127.674.d.1.A',4,'Two postings for the same entry-level programming role list different required tasks. What is the best way to decide which fits your goals?','["Pick the one with the shorter title", "Compare the listed duties against the skills you want to build", "Apply to neither", "Choose whichever has the longer company name"]'::jsonb,1,'Matching duties to your goals is the useful comparison.','original'),
('127.674.d.1.B',3,'A portfolio of finished programs helps an applicant mainly by:','["listing only their hobbies", "replacing the need for any skills", "showing real examples of their work", "hiding their projects from employers"]'::jsonb,2,'Portfolios give employers evidence of ability.','original'),
('127.674.d.1.B',4,'An industry certification on a resume most directly signals that the applicant has:','["finished every college course", "worked ten years in the field", "a guaranteed job offer", "passed an exam proving a specific skill set"]'::jsonb,3,'Certifications verify particular skills.','original'),
('127.674.d.1.C',3,'Before using an unfamiliar method in a library, a programmer should first consult its:','["API documentation", "screen saver", "printer queue", "wallpaper settings"]'::jsonb,0,'Documentation explains how methods are used.','original'),
('127.674.d.1.C',4,'Which comment best supports technical writing standards in a code file?','["An empty line of dashes only", "A short note explaining why the loop skips the first item", "A note saying ''stuff happens here''", "A joke unrelated to the code"]'::jsonb,1,'Good comments explain intent clearly and briefly.','original'),
('127.674.d.1.D',3,'During a code review, a developer disagrees with a suggestion. Which response shows effective verbal communication?','["Interrupt and raise your voice", "Say nothing and ignore the comment", "Explain the reasoning calmly and ask for the reviewer''s view", "Walk away from the meeting"]'::jsonb,2,'Calm, two-way discussion resolves disagreements.','original'),
('127.674.d.1.D',4,'When presenting a program to a non-technical audience, the best approach is to:','["speak quickly to save time", "use as many acronyms as possible", "read the source code line by line", "avoid jargon and use plain examples"]'::jsonb,3,'Audience-aware language improves understanding.','original'),
('127.674.d.1.E',3,'A program crashes only when a list is empty. Which step is the best critical-thinking move?','["Reproduce the crash with an empty list and inspect the code path", "Blame the computer hardware", "Rewrite the whole program at random", "Delete the list feature"]'::jsonb,0,'Reproducing a bug narrows down its cause.','original'),
('127.674.d.1.E',4,'Two algorithms solve the same problem. Which evidence best supports choosing one?','["Which uses more lines of code", "Measured run times on the same sample inputs", "Which one has a catchier name", "Which was written first"]'::jsonb,1,'Fair measurements give objective evidence.','original'),
('127.674.d.1.F',3,'On a software team, the member who keeps the group focused on goals and helps resolve conflicts is demonstrating:','["procrastination", "sabotage", "leadership", "isolation"]'::jsonb,2,'Leaders guide the team toward shared goals.','original'),
('127.674.d.1.F',4,'A teammate is stuck on a bug while you finish early. A strong team member would:','["wait without saying anything", "take credit for the fix later", "leave to avoid the task", "offer help or pair up to solve it"]'::jsonb,3,'Good teammates support one another.','original'),
('127.674.d.1.G',3,'Copying a classmate''s code and submitting it as your own is mainly an issue of:','["academic dishonesty", "good version control", "normal debugging", "efficient reuse"]'::jsonb,0,'Presenting others'' work as yours is dishonest.','original'),
('127.674.d.1.G',4,'A developer discovers that an app collects users'' contacts without telling them. The ethical response is to:','["sell the data", "report the practice and push for user consent", "delete the evidence", "hide it to protect sales"]'::jsonb,1,'Ethical practice requires transparency and consent.','original'),
('127.674.d.1.H',3,'A student has a project due in two weeks. Which habit best demonstrates time management?','["Starting the night before", "Skipping testing time", "Breaking the work into milestones with dates", "Waiting for inspiration"]'::jsonb,2,'Milestones keep work on schedule.','original'),
('127.674.d.1.H',4,'A team estimates 10 hours for coding and 4 for testing but has only 12 hours. The best planning move is to:','["skip the testing silently", "work without a plan", "ignore the estimate", "adjust scope or timeline before work begins"]'::jsonb,3,'Plans should fit the available time.','original'),
('127.674.d.1.I',3,'Which factor would a student most likely compare when choosing between two university computer science programs?','["Course offerings, research areas, and internship partnerships", "The color of the campus signs", "The mascot''s name", "The number of vending machines"]'::jsonb,0,'Academic fit matters most.','original'),
('127.674.d.1.I',4,'A student interested in cybersecurity should look for a program that offers:','["only art electives", "security courses and related labs or clubs", "no faculty advisors", "no computer labs"]'::jsonb,1,'Program strengths should match career interests.','original'),
('127.674.d.2.A',3,'Splitting a large program into smaller, manageable parts is the strategy of:','["compression", "duplication", "decomposition", "deletion"]'::jsonb,2,'Decomposition simplifies big problems.','original'),
('127.674.d.2.A',4,'A programmer sketches inputs, outputs and steps before writing any code. This strategy is called:','["copy-pasting old code", "compiling twice", "debugging after release", "planning the design before coding"]'::jsonb,3,'Design first reduces rework.','original'),
('127.674.d.2.B',3,'Before modifying someone else''s program, a developer should first:','["read the code and its documentation", "delete all comments", "rename every variable", "recompile without reading"]'::jsonb,0,'Understanding comes before changing.','original'),
('127.674.d.2.B',4,'A UML class diagram or API doc accompanying a program mainly helps a programmer:','["remove the need for testing", "understand how the pieces are meant to work together", "make the program run faster automatically", "hide classes from users"]'::jsonb,1,'Documentation explains structure and use.','original'),
('127.674.d.2.C',3,'Which sequence best matches a systematic problem-solving process?','["Test, define, hide, ship", "Refine, ignore, implement, define", "Define the problem, plan, implement, test, refine", "Ship, plan, define, delete"]'::jsonb,2,'A systematic process moves from understanding to refining.','original'),
('127.674.d.2.C',4,'The first step in a systematic problem-solving process is to:','["choose a font", "deploy to users", "write the final code", "identify the purpose and goals of the problem"]'::jsonb,3,'You must know the goal before solving.','original'),
('127.674.d.2.D',3,'Starting with the overall program and breaking it into smaller pieces is which approach?','["top-down design", "reverse linking", "bottom-up design", "random design"]'::jsonb,0,'Top-down begins with the big picture.','original'),
('127.674.d.2.D',4,'Building small reusable routines first, then combining them into a larger program, describes:','["waterfall testing only", "bottom-up design", "black box deletion", "top-down design"]'::jsonb,1,'Bottom-up builds from components.','original'),
('127.674.d.2.E',3,'Tracing a program by hand means:','["running it only on a faster computer", "only reading the comments", "following each statement and recording variable values", "counting its lines of code"]'::jsonb,2,'A trace table shows how values change.','original'),
('127.674.d.2.E',4,'Using a class''s methods without knowing how they work internally is called:','["pointer erasing", "dead code removal", "white noise coding", "black box programming"]'::jsonb,3,'A black box exposes behavior, not internals.','original'),
('127.674.d.2.F',3,'A program must process items in the order they arrive, first in, first out. Which abstract data type fits?','["queue", "stack", "tree", "heap"]'::jsonb,0,'Queues are first-in, first-out.','original'),
('127.674.d.2.F',4,'Which data structure is the best fit for undo history, where the most recent action is reversed first?','["sorted array", "stack", "queue", "hash set"]'::jsonb,1,'Stacks are last-in, first-out.','original'),
('127.674.d.2.G',3,'Bundling data and methods in a class while hiding internal details is called:','["iteration", "compilation", "encapsulation", "recursion"]'::jsonb,2,'Encapsulation protects internal state.','original'),
('127.674.d.2.G',4,'A subclass reusing fields and methods from a parent class demonstrates:','["casting", "hashing", "overflow", "inheritance"]'::jsonb,3,'Inheritance passes members to subclasses.','original'),
('127.674.d.3.A',3,'Why do software teams use shared version control?','["to track changes and let several people work on the same code", "to delete old projects automatically", "to make code run slower", "to prevent anyone from editing files"]'::jsonb,0,'Version control supports collaboration and history.','original'),
('127.674.d.3.A',4,'In a software team, the person responsible for checking that features work as required before release is the:','["office janitor", "tester or quality assurance engineer", "hardware vendor", "marketing intern only"]'::jsonb,1,'QA staff verify software quality.','original'),
('127.674.d.3.B',3,'A problem statement says ''the app must let a user log in and save scores.'' A specific requirement would be:','["the app is fun", "the app looks nice", "the app stores a score for each logged-in user", "the app is popular"]'::jsonb,2,'Requirements must be specific and testable.','original'),
('127.674.d.3.B',4,'Which is a well-written solution requirement?','["The program should be great.", "The program must do stuff.", "The program is easy.", "The program shall accept a whole number from 1 to 10."]'::jsonb,3,'Good requirements are precise and measurable.','original'),
('127.674.d.3.C',3,'A program development plan should include:','["tasks, a schedule, and testing steps", "a list of favorite songs", "only the final code", "only the team''s names"]'::jsonb,0,'Plans organize work before coding.','original'),
('127.674.d.3.C',4,'Which item belongs in a program development plan before coding starts?','["The user reviews after release", "A description of inputs, outputs, and major steps", "A list of bugs found in release", "The finished source code"]'::jsonb,1,'Planning defines what the program must do.','original'),
('127.674.d.3.D',3,'In pair programming, one partner types while the other:','["plays a game", "deletes the files", "reviews the code and suggests improvements", "sleeps"]'::jsonb,2,'The navigator reviews as the driver types.','original'),
('127.674.d.3.D',4,'In pair programming, the driver and navigator roles should be:','["hidden from the team", "never changed", "assigned to a stranger", "switched regularly"]'::jsonb,3,'Switching keeps both partners engaged.','original'),
('127.674.d.3.E',3,'For a program accepting whole numbers 1 to 100, which is a boundary test value?','["100", "37", "50", "73"]'::jsonb,0,'Boundary values sit at the edge of the valid range.','original'),
('127.674.d.3.E',4,'Testing an age field with 0, 1, 119 and 120 when valid ages are 1 to 119 is mostly checking:','["screen brightness", "boundary cases", "file names", "spelling errors"]'::jsonb,1,'Edge values catch off-by-one mistakes.','original'),
('127.674.d.3.F',3,'When reporting a project''s results in a presentation, a team should lead with:','["every line of code", "a list of mistakes only", "the problem, the solution and the results", "an unrelated story"]'::jsonb,2,'A clear story helps the audience follow.','original'),
('127.674.d.3.F',4,'A clear slide about a program''s performance would most effectively use:','["unlabeled numbers only", "a blurry screenshot", "a wall of tiny text", "a simple chart comparing results"]'::jsonb,3,'Charts make comparisons easy to see.','original'),
('127.674.d.4.A',3,'Before reading from a file in a program, the program must first:','["open the file", "rename the program", "print the file", "delete the file"]'::jsonb,0,'A file must be opened before access.','original'),
('127.674.d.4.A',4,'After a program finishes writing data to a file, it should:','["restart the computer", "close the file", "leave it open forever", "erase the data"]'::jsonb,1,'Closing flushes data and frees resources.','original'),
('127.674.d.4.B',3,'A program that reads lines from a text file until there are no more lines is handling a file of:','["fixed color", "hidden type", "unknown length", "negative length"]'::jsonb,2,'Reading until the end suits unknown sizes.','original'),
('127.674.d.4.B',4,'Which loop is best for reading every line of a file when the line count is not known?','["no loop at all", "a loop that runs exactly 10 times", "a loop with no condition", "a loop that continues until end of file"]'::jsonb,3,'The end-of-file condition stops the loop.','original'),
('127.674.d.4.C',3,'In most languages, which string operation returns a portion of a string?','["substring", "comparison", "reversal of loop", "length"]'::jsonb,0,'A substring extracts part of the text.','original'),
('127.674.d.4.C',4,'A program converts every letter of a user''s name to capital letters before comparing it. This is an example of:','["loop unrolling", "string manipulation", "array sorting", "file closing"]'::jsonb,1,'Changing case is a string operation.','original'),
('127.674.d.4.D',3,'Converting an integer value into a decimal (floating-point) value is an example of:','["file closing", "array sorting", "type casting", "loop nesting"]'::jsonb,2,'Casting changes a value''s data type.','original'),
('127.674.d.4.D',4,'In Java, what is the result of (int) 7.9?','["0", "8", "7.9", "7"]'::jsonb,3,'Casting a double to int truncates the decimal part.','original'),
('127.674.d.4.E',3,'In an array of 10 elements in most languages, the index of the last element is:','["9", "10", "11", "0"]'::jsonb,0,'Indexes start at 0.','original'),
('127.674.d.4.E',4,'To find the largest value in a one-dimensional array of scores, a program should:','["print only the first element", "traverse the array while tracking the biggest value seen", "delete every element", "sort the array backwards twice"]'::jsonb,1,'Traversal with a running maximum finds the largest.','original'),
('127.674.d.4.F',3,'A table stored in a 2-D array with 3 rows and 4 columns holds how many elements?','["34", "1", "12", "7"]'::jsonb,2,'3 times 4 equals 12.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_82_v1'
from (values
('127.674.d.4.F',4,'Which structure of loops is typically used to visit every cell in a 2-D array?','["a constant", "a lone if statement", "a single print", "nested loops"]'::jsonb,3,'One loop for rows, one for columns.','original'),
('127.674.d.4.G',3,'Compared with a fixed-size array, a list object can usually:','["grow or shrink as items are added or removed", "store only text", "never be searched", "hold only one item"]'::jsonb,0,'Lists resize dynamically.','original'),
('127.674.d.4.G',4,'Which operation places a new item in the middle of a list object?','["close the list", "insert at a chosen index", "cast the index", "reverse the compiler"]'::jsonb,1,'Insert adds an element at a position.','original'),
('127.674.d.4.H',3,'Which category of language is closest to the hardware and uses binary instructions?','["scripting language", "markup language", "machine language", "high-level language"]'::jsonb,2,'Machine code is binary instructions.','original'),
('127.674.d.4.H',4,'Python and Java are examples of:','["hardware drivers", "assembly languages", "machine code", "high-level languages"]'::jsonb,3,'High-level languages are human readable.','original'),
('127.674.d.5.A',3,'An if statement placed inside the body of another if statement is called:','["a nested conditional", "a loop counter", "a casting step", "a recursive call"]'::jsonb,0,'Nested branching tests a second condition inside the first.','original'),
('127.674.d.5.A',4,'if (x > 0) { if (x < 10) print(''small''); } What prints when x is 15?','["an error", "nothing", "0", "small"]'::jsonb,1,'The inner condition fails, so no print runs.','original'),
('127.674.d.5.B',3,'Which statement is best for choosing among many fixed integer cases such as menu options 1 to 5?','["import", "for-each", "switch", "while"]'::jsonb,2,'A switch selects among discrete values.','original'),
('127.674.d.5.B',4,'In a switch statement, forgetting break at the end of a case usually causes:','["all cases to be deleted", "the program to skip compiling", "the variable to be reset", "execution to fall through to the next case"]'::jsonb,3,'Without break, execution continues into the next case.','original'),
('127.674.d.5.C',3,'In (a != 0 && 10 / a > 1), why does the program not divide by zero when a is 0?','["the first condition is false, so the second is never evaluated", "division by zero is allowed", "the compiler removes the zero", "the operator swaps the values"]'::jsonb,0,'Short-circuit evaluation skips the second test.','original'),
('127.674.d.5.C',4,'With short-circuit evaluation, in (x == 5 || y()), when does y() run?','["always", "only when x == 5 is false", "only when x equals 5", "never"]'::jsonb,1,'OR stops as soon as the first operand is true.','original'),
('127.674.d.5.D',3,'By De Morgan''s Law, NOT (A AND B) is equivalent to:','["A OR B", "NOT A AND NOT B", "NOT A OR NOT B", "A AND B"]'::jsonb,2,'Negating an AND flips it to OR of negations.','original'),
('127.674.d.5.D',4,'Using De Morgan''s Law, NOT (A OR B) simplifies to:','["A AND B", "NOT A OR NOT B", "A OR NOT B", "NOT A AND NOT B"]'::jsonb,3,'Negating an OR flips it to AND of negations.','original'),
('127.674.d.5.E',3,'A nested for loop where the outer loop runs 3 times and the inner loop runs 4 times executes the inner body how many times in total?','["12", "3", "7", "16"]'::jsonb,0,'3 times 4 equals 12.','original'),
('127.674.d.5.E',4,'Which task is a typical use of nested loops?','["opening one file", "printing a multiplication table", "declaring a constant", "adding two numbers"]'::jsonb,1,'Rows and columns need two loops.','original'),
('127.674.d.5.F',3,'A recursive method must have a base case in order to:','["run faster than loops", "declare variables", "stop calling itself", "avoid compiling"]'::jsonb,2,'The base case ends the recursion.','original'),
('127.674.d.5.F',4,'What is factorial(4) if factorial(n) = n * factorial(n-1) and factorial(0) = 1?','["16", "10", "12", "24"]'::jsonb,3,'4 x 3 x 2 x 1 = 24.','original'),
('127.674.d.5.G',3,'Binary search requires the list to be:','["sorted", "empty", "reversed twice", "all equal"]'::jsonb,0,'Binary search relies on order.','original'),
('127.674.d.5.G',4,'Searching a sorted list of 1,024 items with binary search takes about how many comparisons?','["100", "10", "1,024", "512"]'::jsonb,1,'2 to the 10th power is 1,024.','original'),
('127.674.d.5.H',3,'Which sort repeatedly swaps adjacent items that are out of order?','["linear search", "binary search", "bubble sort", "hash table lookup"]'::jsonb,2,'Bubble sort swaps neighbors.','original'),
('127.674.d.5.H',4,'Which sorting algorithm divides the list in half, sorts each half and merges the results?','["bubble sort", "selection sort", "insertion sort", "merge sort"]'::jsonb,3,'Merge sort uses divide and conquer.','original'),
('127.674.d.5.I',3,'A loop that visits each of n items exactly once has time complexity:','["O(n)", "O(n squared)", "O(log n)", "O(1)"]'::jsonb,0,'One pass is linear time.','original'),
('127.674.d.5.I',4,'Which Big-O class grows fastest as n becomes large?','["O(n)", "O(n squared)", "O(log n)", "O(1)"]'::jsonb,1,'Quadratic grows faster than linear or logarithmic.','original'),
('127.674.d.5.J',3,'Which loop idea computes 1 + 2 + 3 + ... + n?','["sort the digits", "reverse the string", "accumulate a running total as the counter increases", "print n once"]'::jsonb,2,'A running sum adds each term.','original'),
('127.674.d.5.J',4,'To list the factors of n, a program can test each number from 1 to n using the:','["concatenation operator", "assignment alone", "casting operator", "remainder (modulus) operator"]'::jsonb,3,'A factor leaves remainder 0.','original'),
('127.674.d.5.K',3,'A unit test targets a single:','["method or class", "monitor", "network cable", "user''s desk"]'::jsonb,0,'Unit tests isolate small pieces of code.','original'),
('127.674.d.5.K',4,'A method returns the average of an array. Which input is an important boundary test?','["an array in another font", "an empty array", "the same array printed twice", "a very colorful array"]'::jsonb,1,'Empty input can cause division by zero.','original'),
('127.674.d.5.L',3,'A missing semicolon or unmatched bracket is a:','["hardware error", "runtime error", "syntax error", "logic error"]'::jsonb,2,'Syntax errors break language rules.','original'),
('127.674.d.5.L',4,'A program compiles but prints the wrong average because it divides by the wrong number. This is a:','["linker error", "compile error", "syntax error", "logic error"]'::jsonb,3,'Logic errors produce wrong results without crashing.','original'),
('127.674.d.5.M',3,'Informally, doubling the input size makes a linear algorithm take about:','["twice as long", "half as long", "the same time", "four times as long"]'::jsonb,0,'Linear time scales proportionally.','original'),
('127.674.d.5.M',4,'For 1,000,000 sorted items, which finds a target in the fewest steps?','["linear search", "binary search", "bubble sort", "random guessing"]'::jsonb,1,'Binary search halves the range each step.','original'),
('127.674.d.5.N',3,'The hexadecimal number 1F equals what in decimal?','["47", "16", "31", "15"]'::jsonb,2,'1 x 16 + 15 = 31.','original'),
('127.674.d.5.N',4,'The binary number 101101 equals what in decimal?','["37", "53", "43", "45"]'::jsonb,3,'32 + 8 + 4 + 1 = 45.','original'),
('127.674.d.5.O',3,'A signed 8-bit integer holds values from -128 to 127. Adding 1 to 127 may cause:','["overflow", "a recursion", "a syntax error", "a sorted list"]'::jsonb,0,'The result exceeds the maximum value.','original'),
('127.674.d.5.O',4,'In many languages, 0.1 + 0.2 does not exactly equal 0.3 because of:','["string joining", "limited precision in floating-point storage", "integer division", "syntax rules"]'::jsonb,1,'Binary cannot represent some decimals exactly.','original'),
('127.674.d.5.P',3,'A math library function such as pow(2, 3) returns:','["6", "9", "8", "5"]'::jsonb,2,'2 to the 3rd power is 8.','original'),
('127.674.d.5.P',4,'Which math library function would return the larger of two numbers?','["abs", "sqrt", "round", "max"]'::jsonb,3,'max compares and returns the greater value.','original'),
('127.674.d.5.Q',3,'A simulation of flipping a fair coin could use a random integer that is either:','["0 or 1", "5 or 9", "1 or 6", "any decimal"]'::jsonb,0,'Two outcomes map to two values.','original'),
('127.674.d.5.Q',4,'Seeding a random number generator with the same value each run will usually produce:','["a different sequence each time", "the same sequence of numbers", "only negative numbers", "no numbers"]'::jsonb,1,'Seeds make pseudorandom output repeatable.','original'),
('127.674.d.5.R',3,'A Car class that contains an Engine object demonstrates:','["inheritance", "overloading", "composition", "recursion"]'::jsonb,2,'Composition models a has-a relationship.','original'),
('127.674.d.5.R',4,'Which relationship is best modeled by inheritance?','["A Car has an Engine", "A Team has Players", "A Student has a Backpack", "A Dog is an Animal"]'::jsonb,3,'Inheritance models is-a relationships.','original'),
('127.674.d.5.S',3,'A class that cannot be instantiated and may contain unfinished methods is:','["abstract", "final loop", "primitive", "static"]'::jsonb,0,'Abstract classes are meant to be extended.','original'),
('127.674.d.5.S',4,'A Java interface mainly specifies:','["a program''s colors", "methods a class must provide", "a file''s location", "a class''s private data"]'::jsonb,1,'Interfaces define required behavior.','original'),
