('127.674.d.5.T',4,'Which declaration inside a class stores each object''s own data?','["import statement", "main method", "package name", "instance variable"]'::jsonb,3,'Instance variables belong to each object.','original'),
('127.674.d.5.U',3,'When a call to speak() behaves differently for Dog and Cat objects, this is:','["polymorphism", "encapsulation", "casting", "iteration"]'::jsonb,0,'Same call, different behavior by type.','original'),
('127.674.d.5.U',4,'Polymorphism lets a variable of a parent type refer to:','["unrelated files", "objects of its subclasses", "only itself", "only primitives"]'::jsonb,1,'Subclass objects can stand in for the parent type.','original'),
('127.674.d.5.V',3,'Two reference variables pointing to the same object means:','["the object is deleted", "they cannot be compared", "changes through one are seen through the other", "they hold separate copies"]'::jsonb,2,'Both references share one object.','original'),
('127.674.d.5.V',4,'A reference variable that currently refers to no object holds:','["an empty array of ints", "zero bytes", "a copy", "null"]'::jsonb,3,'null means no object.','original'),
