('127.676.d.2.B',3,'In the U.S., the Computer Fraud and Abuse Act mainly makes it illegal to:','["use a password", "own a laptop", "access computers without authorization", "buy software"]'::jsonb,2,'The CFAA targets unauthorized access.','original'),
('127.676.d.2.B',4,'The European Union''s GDPR is a law mainly about:','["taxing software sales", "regulating video game ratings", "setting internet speeds", "protecting personal data and privacy"]'::jsonb,3,'GDPR governs personal data.','original'),
('127.676.d.2.C',3,'The 2017 WannaCry attack spread worldwide by encrypting files and demanding payment, making it a:','["ransomware attack", "spreadsheet error", "phishing newsletter", "hardware recall"]'::jsonb,0,'WannaCry was ransomware.','original'),
('127.676.d.2.C',4,'The 2013 Target data breach began when attackers used credentials stolen from a:','["weather service", "third-party vendor", "school student", "local newspaper"]'::jsonb,1,'Vendor access was the entry point.','original'),
('127.676.d.2.D',3,'A coworker asks you to share your login so they can finish a report. The best response is to:','["share it quickly", "email it", "decline and have them request their own access", "post it on a note"]'::jsonb,2,'Credentials should never be shared.','original'),
('127.676.d.2.D',4,'A friend offers pirated paid software as a gift. Considering law and ethics, you should:','["hide the source", "accept and share it", "sell it", "decline and use a licensed or free legal alternative"]'::jsonb,3,'Piracy is illegal and unethical.','original'),
('127.676.d.2.E',3,'An attacker calls pretending to be IT support to get your password. This tactic is:','["social engineering", "port forwarding", "disk defragmentation", "cache clearing"]'::jsonb,0,'It manipulates people rather than technology.','original'),
('127.676.d.2.E',4,'Software designed to damage or gain unauthorized access to a system is called:','["middleware", "malware", "firmware", "freeware"]'::jsonb,1,'Malware is malicious software.','original'),
('127.676.d.2.F',3,'Why should you cite sources when using information from a security report?','["to avoid reading the report", "to make the report longer", "to give credit and let readers verify the information", "to hide where the data came from"]'::jsonb,2,'Citations give credit and support verification.','original'),
('127.676.d.2.F',4,'Which item is a necessary part of most citations?','["a favorite color", "a random number", "the reader''s address", "author and title of the source"]'::jsonb,3,'Citations identify the work and its creator.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_82_v1'
from (values
('127.676.d.3.A',3,'Which is a common motivation for cybercriminals?','["financial gain", "bus schedules", "weather curiosity", "needing sleep"]'::jsonb,0,'Many attacks aim to make money.','original'),
('127.676.d.3.A',4,'Some attackers hack to promote a political or social cause rather than for money. They are motivated by:','["shoe size", "ideology or activism", "a favorite food", "boredom with television"]'::jsonb,1,'Hacktivists act for a cause.','original'),
('127.676.d.3.B',3,'A group that attacks systems to promote a social or political message is called:','["system patches", "network cables", "hacktivists", "script editors"]'::jsonb,2,'Hacktivists mix hacking and activism.','original'),
('127.676.d.3.B',4,'Attacks sponsored by a government to spy on other nations are carried out by:','["random pop-ups", "hardware vendors", "local hobbyists only", "state-sponsored actors"]'::jsonb,3,'Nation-states run espionage campaigns.','original'),
('127.676.d.3.C',3,'A cyberattack on a hospital that locks patient records can:','["delay patient care and endanger lives", "improve patient care", "reduce all costs", "make the network faster"]'::jsonb,0,'Hospitals depend on data access.','original'),
('127.676.d.3.C',4,'Large-scale cyberattacks can harm society by disrupting:','["only music", "banking, utilities and communications", "nothing at all", "only paper mail"]'::jsonb,1,'Modern services depend on networks.','original'),
('127.676.d.3.D',3,'A hacker who breaks into systems with permission to help improve security is a:','["blue screen", "red flag", "white hat", "black hat"]'::jsonb,2,'White hats are ethical hackers.','original'),
('127.676.d.3.D',4,'A hacker who looks for flaws without permission but may report them rather than exploit them is often called a:','["contracted pen tester", "system administrator", "ransomware author", "gray hat"]'::jsonb,3,'Gray hats operate between legal lines.','original'),
('127.676.d.3.E',3,'Ethical hackers differ from criminals mainly because they have:','["written permission to test the system", "more followers", "secret passwords", "faster computers"]'::jsonb,0,'Authorization makes testing legal.','original'),
('127.676.d.3.E',4,'Hacking a company''s network without permission, even without stealing anything, can result in:','["a free reward", "criminal charges and fines", "a certificate", "a promotion"]'::jsonb,1,'Unauthorized access is illegal.','original'),
('127.676.d.4.A',3,'Cyberterrorism is the use of attacks on computer systems to:','["sell office furniture", "improve typing speed", "cause fear, disruption or harm for political aims", "teach coding"]'::jsonb,2,'Cyberterrorism pursues political goals through fear.','original'),
('127.676.d.4.A',4,'Hacktivism differs from cyberterrorism in that hacktivists usually aim mainly to:','["sell stolen goods", "repair networks", "cause mass physical casualties", "protest or spread a message"]'::jsonb,3,'Hacktivism is typically protest-driven.','original'),
('127.676.d.4.B',3,'One difference between cyberterrorism and physical terrorism is that cyberattacks can be launched:','["remotely from anywhere in the world", "only from inside the target building", "only in daylight", "only with explosives"]'::jsonb,0,'Attackers need only a network connection.','original'),
('127.676.d.4.B',4,'Terrorism carried out by citizens against their own country''s targets is called:','["foreign trade", "domestic terrorism", "international terrorism", "state tourism"]'::jsonb,1,'Domestic means within the same country.','original'),
('127.676.d.4.C',3,'Collecting information about a target before an attack or defense is called:','["file compression", "screen mirroring", "intelligence gathering", "data deletion"]'::jsonb,2,'Reconnaissance gathers intelligence.','original'),
('127.676.d.4.C',4,'Using public sources like websites and social media to collect information is known as:','["rootkit install", "packet loss", "disk imaging", "open-source intelligence (OSINT)"]'::jsonb,3,'OSINT uses publicly available data.','original'),
('127.676.d.4.D',3,'Why do governments invest in cyber defense?','["to protect critical systems and national security", "to remove all computers", "to slow the economy", "to reduce passwords"]'::jsonb,0,'Cyber defense protects national interests.','original'),
('127.676.d.4.D',4,'A corporation''s cyber defense protects:','["nothing digital", "its customer data and trade secrets", "its competitors'' data", "only its logo"]'::jsonb,1,'Companies guard valuable data.','original'),
('127.676.d.4.E',3,'Strong cyber defense supports the global economy by:','["stopping all trade", "raising all prices", "keeping online commerce and finance trustworthy", "removing banks"]'::jsonb,2,'Trust underpins digital business.','original'),
('127.676.d.4.E',4,'When consumers lose trust in online security, the likely economic effect is:','["free internet", "more online payments", "lower inflation always", "less online shopping and banking"]'::jsonb,3,'Distrust reduces digital activity.','original'),
('127.676.d.4.F',3,'Which is an example of public infrastructure targeted by cyberattacks?','["the electrical power grid", "a toy store", "a cookbook", "a private diary"]'::jsonb,0,'Power grids are critical infrastructure.','original'),
('127.676.d.4.F',4,'A successful attack on a water treatment plant''s control system could:','["have no effect", "endanger public health and safety", "reduce the need for pipes", "improve water quality automatically"]'::jsonb,1,'Control systems manage safe treatment.','original'),
('127.676.d.5.A',3,'Privacy is a person''s ability to:','["share everything", "see everyone''s data", "control who has access to their personal information", "avoid all technology"]'::jsonb,2,'Privacy is about control over information.','original'),
('127.676.d.5.A',4,'Why is privacy valuable to individuals?','["it speeds up internet", "it removes laws", "it makes passwords unnecessary", "it protects safety, freedom and personal choice"]'::jsonb,3,'Privacy shields people from harm and pressure.','original'),
('127.676.d.5.B',3,'The trail of data you leave by browsing, posting and using apps is your:','["digital footprint", "hard drive", "file path", "screen time bar"]'::jsonb,0,'Your footprint is your online data trail.','original'),
('127.676.d.5.B',4,'A negative impact of a large digital footprint can be:','["stronger passwords", "employers or others finding old posts about you", "fewer ads", "faster downloads"]'::jsonb,1,'Old posts can surface later.','original'),
('127.676.d.5.C',3,'Smart speakers and cameras raise privacy concerns because they can:','["improve printing", "remove viruses", "collect data about people at home", "lower electricity"]'::jsonb,2,'Always-on sensors gather personal data.','original'),
('127.676.d.5.C',4,'Facial recognition in public places raises concerns mainly about:','["battery life", "screen resolution", "typing speed", "tracking people without their consent"]'::jsonb,3,'It enables mass surveillance.','original'),
('127.676.d.5.D',3,'Repeated online messages meant to harass or humiliate someone are called:','["cyberbullying", "network sharing", "cloud syncing", "file streaming"]'::jsonb,0,'This is harassment via technology.','original'),
('127.676.d.5.D',4,'A possible sign that a student is being cyberbullied is:','["getting more invitations", "becoming upset after using a phone and avoiding school", "sleeping better", "feeling more confident online"]'::jsonb,1,'Distress tied to devices can signal bullying.','original'),
('127.676.d.5.E',3,'A good first step if you are targeted by cyberbullying is to:','["post personal details of the bully", "delete the evidence", "save evidence and tell a trusted adult", "reply with worse insults"]'::jsonb,2,'Evidence and adult help support action.','original'),
('127.676.d.5.E',4,'Most social media platforms let users deal with abusive accounts by:','["sharing their messages widely", "ignoring settings", "paying them", "blocking and reporting them"]'::jsonb,3,'Block and report tools stop contact and alert moderators.','original'),
('127.676.d.6.A',3,'Which is an example of personally identifiable information (PII)?','["a Social Security number", "a public weather report", "a movie title", "a favorite color"]'::jsonb,0,'SSNs identify specific people.','original'),
('127.676.d.6.A',4,'PII is information that can be used to:','["print a document", "identify a specific person", "speed up a computer", "color a screen"]'::jsonb,1,'PII points to an individual.','original'),
('127.676.d.6.B',3,'Sharing your full birth date and address online increases the risk of:','["better grades", "fewer emails", "identity theft", "faster internet"]'::jsonb,2,'Criminals use PII to impersonate victims.','original'),
('127.676.d.6.B',4,'A benefit of sharing PII with a trusted bank is that it:','["makes your account public", "removes security", "guarantees no fraud", "allows the bank to verify you and provide services"]'::jsonb,3,'Verification enables legitimate services.','original'),
('127.676.d.6.C',3,'A flashlight app asking for access to your contacts and microphone is requesting:','["unnecessary permissions", "a screen repair", "a battery update", "standard lighting"]'::jsonb,0,'The app does not need that data.','original'),
('127.676.d.6.C',4,'Granting excessive app permissions can let an app:','["increase battery life", "collect or expose data it does not need", "block ads automatically", "fix bugs"]'::jsonb,1,'Extra permissions expand data exposure.','original'),
('127.676.d.6.D',3,'Allowing a third-party app to access your social media account can risk:','["a stronger password", "less data sharing", "your data being shared or misused", "free storage"]'::jsonb,2,'Third parties may mishandle data.','original'),
('127.676.d.6.D',4,'To limit risk, a user should periodically:','["disable updates", "grant every request", "share passwords", "review and remove third-party app access"]'::jsonb,3,'Pruning access reduces exposure.','original'),
('127.676.d.6.E',3,'Clicking ''I agree'' on terms of service without reading can mean you:','["accept data collection or sharing you did not review", "receive extra security", "lose no rights", "get a refund"]'::jsonb,0,'Terms often include data permissions.','original'),
('127.676.d.6.E',4,'A terms-of-service document is a:','["network map", "legal agreement between user and provider", "password list", "virus signature"]'::jsonb,1,'ToS sets legal rules of use.','original'),
('127.676.d.7.A',3,'Cybersecurity is the practice of:','["writing music", "building faster screens", "protecting systems, networks and data from digital attacks", "designing fonts"]'::jsonb,2,'Cybersecurity defends against digital threats.','original'),
('127.676.d.7.A',4,'Information security is broader than cybersecurity in that it protects information:','["only in clouds", "only on websites", "only in email", "in any form, including paper"]'::jsonb,3,'Infosec covers all information formats.','original'),
('127.676.d.7.B',3,'A risk assessment identifies:','["threats, vulnerabilities and potential impact", "only the cheapest tools", "employee birthdays", "the best desktop wallpaper"]'::jsonb,0,'Assessments evaluate what could go wrong.','original'),
('127.676.d.7.B',4,'Risk is commonly estimated by considering the likelihood of an event and its:','["color", "impact", "shape", "speed of typing"]'::jsonb,1,'Risk combines likelihood and impact.','original'),
('127.676.d.7.C',3,'In the CIA triad, ''confidentiality'' means:','["files are always compressed", "systems are always online", "only authorized people can access information", "data is never changed by anyone"]'::jsonb,2,'Confidentiality restricts access.','original'),
('127.676.d.7.C',4,'Keeping data accurate and unaltered by unauthorized users is the goal of:','["portability", "availability", "anonymity", "integrity"]'::jsonb,3,'Integrity protects accuracy.','original'),
('127.676.d.7.D',3,'Using the same easy password everywhere is convenient but reduces:','["security", "screen size", "battery life", "file count"]'::jsonb,0,'Convenience often weakens protection.','original'),
('127.676.d.7.D',4,'Requiring multi-factor authentication improves security but may reduce:','["encryption", "convenience", "accuracy of logs", "server uptime"]'::jsonb,1,'Extra steps slow users down.','original'),
('127.676.d.7.E',3,'After detecting a breach, the first priority is usually to:','["rename the servers", "announce a sale", "contain the incident to stop further damage", "delete all logs"]'::jsonb,2,'Containment limits the spread.','original'),
('127.676.d.7.E',4,'An incident response plan typically includes preparation, detection, containment, eradication, recovery and:','["hiring a mascot", "advertising", "a holiday party", "lessons learned"]'::jsonb,3,'Reviews improve future response.','original'),
('127.676.d.7.F',3,'Locks, badges and security cameras address which domain of security?','["physical security", "network security", "software licensing", "cloud billing"]'::jsonb,0,'These protect physical spaces.','original'),
('127.676.d.7.F',4,'Misconfigured cloud storage that exposes data publicly is a challenge in:','["print security", "cloud security", "paper filing", "physical security"]'::jsonb,1,'Cloud settings must be configured correctly.','original'),
('127.676.d.7.G',3,'A common challenge for cybersecurity professionals is that attackers:','["never change tactics", "never use computers", "constantly develop new techniques", "always announce attacks"]'::jsonb,2,'Threats evolve continually.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
