select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_82_v1'
from (values
('127.676.d.7.G',4,'A shortage of trained workers is a challenge in cybersecurity known as the:','["memory leak", "wireless dead zone", "screen gap", "skills gap"]'::jsonb,3,'Demand exceeds trained talent.','original'),
('127.676.d.7.H',3,'An indicator of compromise (IOC) is:','["evidence that a system may have been breached", "a software coupon", "a graphics card", "a backup schedule"]'::jsonb,0,'IOCs signal a possible intrusion.','original'),
('127.676.d.7.H',4,'Which is a common warning sign that a computer may be compromised?','["a clean desktop", "unexpected programs running and unusual network traffic", "a quiet fan only", "a new keyboard"]'::jsonb,1,'Odd activity can indicate infection.','original'),
('127.676.d.7.I',3,'Many IoT devices are vulnerable because they often have:','["too much encryption", "no internet", "default passwords and weak updates", "strong firewalls"]'::jsonb,2,'IoT devices frequently ship insecure.','original'),
('127.676.d.7.I',4,'Changing the default credentials on a smart camera helps prevent:','["battery drain", "slow video", "screen glare", "unauthorized remote access"]'::jsonb,3,'Defaults are widely known to attackers.','original'),
('127.676.d.7.J',3,'A weakness in software that an attacker could exploit is called a:','["vulnerability", "cookie", "patch cable", "firewall"]'::jsonb,0,'A vulnerability is a flaw.','original'),
('127.676.d.7.J',4,'The method or code used to take advantage of a vulnerability is an:','["update", "exploit", "antenna", "archive"]'::jsonb,1,'Exploits abuse vulnerabilities.','original'),
('127.676.d.7.K',3,'Penetration testing is:','["repairing monitors", "a way to make passwords public", "an authorized simulated attack to find weaknesses", "random deletion of files"]'::jsonb,2,'Pen tests are permitted simulated attacks.','original'),
('127.676.d.7.K',4,'Which tool is commonly used by penetration testers to scan for open ports?','["Photoshop", "Notepad", "Excel", "Nmap"]'::jsonb,3,'Nmap maps hosts and ports.','original'),
('127.676.d.7.L',3,'The MITRE ATT&CK framework is a knowledge base of:','["adversary tactics and techniques", "fonts", "programming syntax", "video game cheats"]'::jsonb,0,'ATT&CK catalogs real attacker behavior.','original'),
('127.676.d.7.L',4,'The NIST Cybersecurity Framework organizes security activities into functions such as identify, protect, detect, respond and:','["advertise", "recover", "decorate", "entertain"]'::jsonb,1,'Recover completes the core functions.','original'),
('127.676.d.8.A',3,'Malware that secretly records what a user does and sends it to an attacker is:','["a backup tool", "a driver", "spyware", "a firmware update"]'::jsonb,2,'Spyware monitors users covertly.','original'),
('127.676.d.8.A',4,'Malware that encrypts a victim''s files and demands payment is:','["an updater", "spyware", "a rootkit", "ransomware"]'::jsonb,3,'Ransomware holds data hostage.','original'),
('127.676.d.8.B',3,'Malware that disguises itself as legitimate software is called a:','["Trojan horse", "worm", "firewall", "patch"]'::jsonb,0,'Trojans trick users into installing them.','original'),
('127.676.d.8.B',4,'Malware that spreads by itself across networks without a user opening a file is a:','["cookie", "worm", "macro", "Trojan horse"]'::jsonb,1,'Worms self-replicate.','original'),
('127.676.d.8.C',3,'Ransomware-as-a-service lets criminals:','["eliminate viruses", "report attacks to police", "rent malware tools from developers", "delete their own malware"]'::jsonb,2,'Developers lease ready-made tools.','original'),
('127.676.d.8.C',4,'The as-a-service model has increased cybercrime because it:','["requires more skill", "bans all malware", "makes attacks illegal to rent", "lowers the skill needed to launch attacks"]'::jsonb,3,'Less technical criminals can attack.','original'),
('127.676.d.8.D',3,'Analysts reverse engineer malware to:','["understand how it works and build detections", "advertise it", "spread it faster", "hide it"]'::jsonb,0,'Analysis supports defenses.','original'),
('127.676.d.8.D',4,'Examining a suspicious program in an isolated environment so it cannot harm the network is called using a:','["spreadsheet", "sandbox", "mailbox", "playlist"]'::jsonb,1,'Sandboxes contain risky code.','original'),
('127.676.d.8.E',3,'Antivirus software commonly detects threats by comparing files to known:','["playlists", "fonts", "signatures", "wallpapers"]'::jsonb,2,'Signatures identify known malware.','original'),
('127.676.d.8.E',4,'Endpoint detection and response (EDR) tools monitor devices to:','["print documents", "raise screen brightness", "compress photos", "detect and respond to suspicious activity"]'::jsonb,3,'EDR watches and responds on endpoints.','original'),
('127.676.d.9.A',3,'System hardening means:','["reducing a system''s attack surface by securing its configuration", "turning off all security", "adding more advertisements", "making hardware heavier"]'::jsonb,0,'Hardening shrinks exposure.','original'),
('127.676.d.9.A',4,'Which is an example of system hardening?','["using default passwords", "disabling unused services and ports", "skipping updates", "opening all ports"]'::jsonb,1,'Fewer open doors means fewer attacks.','original'),
('127.676.d.9.B',3,'The principle of least privilege says users should have:','["no accounts at all", "shared admin passwords", "only the access needed for their tasks", "full admin rights by default"]'::jsonb,2,'Minimal access limits damage.','original'),
('127.676.d.9.B',4,'Running daily tasks from an administrator account is risky because malware would then:','["run slower only", "have no effects", "lose all access", "gain high-level privileges"]'::jsonb,3,'Admin rights amplify damage.','original'),
('127.676.d.9.C',3,'A patch is a software update that mostly:','["fixes security flaws and bugs", "deletes users", "changes the screen color", "adds advertisements"]'::jsonb,0,'Patches repair known problems.','original'),
('127.676.d.9.C',4,'Unpatched operating systems are risky because attackers:','["lose interest", "can use publicly known vulnerabilities", "need physical access always", "cannot find them"]'::jsonb,1,'Known flaws are easy to exploit.','original'),
('127.676.d.9.D',3,'Turning on automatic software updates helps ensure:','["fewer apps work", "passwords reset daily", "security fixes are installed promptly", "the device never restarts"]'::jsonb,2,'Automation reduces delay.','original'),
('127.676.d.9.D',4,'Delaying updates for months can leave users exposed to:','["lower prices", "new wallpapers", "better battery", "known exploits"]'::jsonb,3,'Old software keeps old flaws.','original'),
('127.676.d.9.E',3,'Services that a computer does not need should be:','["disabled", "made public", "hidden in email", "multiplied"]'::jsonb,0,'Unneeded services add risk.','original'),
('127.676.d.9.E',4,'Changing default service settings, such as default accounts and ports, helps because defaults are:','["impossible to change", "well known to attackers", "always encrypted", "legally required"]'::jsonb,1,'Attackers try defaults first.','original'),
('127.676.d.9.F',3,'The 3-2-1 backup rule suggests keeping three copies of data on two types of media with:','["zero copies", "no copies online", "one copy offsite", "all copies in one room"]'::jsonb,2,'An offsite copy survives local disasters.','original'),
('127.676.d.9.F',4,'Regular backups help recover from ransomware because you can:','["skip passwords", "delete the OS", "avoid updating", "restore files without paying"]'::jsonb,3,'Backups remove the need to pay.','original'),
('127.676.d.9.G',3,'Enabling a host firewall helps secure a computer by:','["filtering unwanted network traffic", "speeding up printing", "adding storage", "increasing screen size"]'::jsonb,0,'Firewalls allow or block traffic.','original'),
('127.676.d.9.G',4,'Full-disk encryption protects data if a laptop is:','["plugged in", "lost or stolen", "renamed", "updated"]'::jsonb,1,'Encrypted disks are unreadable without a key.','original'),
('127.676.d.9.H',3,'Employees who lack security training are more likely to:','["patch servers", "report all threats", "fall for phishing emails", "use strong passwords"]'::jsonb,2,'Untrained users are easier targets.','original'),
('127.676.d.9.H',4,'Regular security awareness training mainly helps reduce:','["electricity costs", "screen glare", "paper use", "human error"]'::jsonb,3,'Training changes user behavior.','original'),
('127.676.d.10.A',3,'Which device connects different networks and forwards packets between them?','["router", "hub", "switch", "monitor"]'::jsonb,0,'Routers link networks together.','original'),
('127.676.d.10.A',4,'A switch mainly connects devices within the same:','["planet", "local network", "power outlet", "printer"]'::jsonb,1,'Switches operate inside a LAN.','original'),
('127.676.d.10.B',3,'An IP address identifies:','["a keyboard layout", "a screen resolution", "a device on a network", "a file type"]'::jsonb,2,'IP addresses locate devices.','original'),
('127.676.d.10.B',4,'Which is an example of an IPv4 address format?','["12-34-56", "abc.def.ghi", "192.168.1.1.1.1", "192.168.1.10"]'::jsonb,3,'IPv4 uses four numbers from 0 to 255.','original'),
('127.676.d.10.C',3,'A firewall rule that blocks all incoming traffic on port 23 (Telnet) prevents:','["remote Telnet connections to that device", "all web browsing", "screen sharing only", "local printing"]'::jsonb,0,'Blocking a port stops that service''s traffic.','original'),
('127.676.d.10.C',4,'Firewalls often follow the idea of ''default deny'', which means traffic is:','["allowed unless blocked", "blocked unless a rule allows it", "logged but ignored", "encrypted by default"]'::jsonb,1,'Default deny is the safer posture.','original'),
('127.676.d.10.D',3,'Port 22 is commonly used for:','["email delivery (SMTP)", "web browsing (HTTP)", "Secure Shell (SSH)", "Telnet"]'::jsonb,2,'SSH uses port 22.','original'),
('127.676.d.10.D',4,'HTTPS web traffic normally uses port:','["21", "80", "25", "443"]'::jsonb,3,'HTTPS defaults to 443.','original'),
('127.676.d.10.E',3,'Ports 20 and 21 are used by:','["File Transfer Protocol (FTP)", "HTTPS", "DNS", "Secure Shell"]'::jsonb,0,'FTP uses ports 20 and 21.','original'),
('127.676.d.10.E',4,'Telnet (port 23) is considered risky because it sends data:','["only at night", "unencrypted, including passwords", "encrypted twice", "to no one"]'::jsonb,1,'Telnet is plain text.','original'),
('127.676.d.10.F',3,'Which tool captures and analyzes network packets?','["Notepad", "Calculator", "Wireshark", "Paint"]'::jsonb,2,'Wireshark is a packet analyzer.','original'),
('127.676.d.10.F',4,'Nmap is commonly used to:','["write essays", "edit photos", "play music", "discover hosts and open ports"]'::jsonb,3,'Nmap scans networks.','original'),
('127.676.d.11.A',3,'Which password is strongest?','["Tr!ckyL0ngPassphrase#47", "qwerty", "password123", "12345678"]'::jsonb,0,'Length and variety add strength.','original'),
('127.676.d.11.A',4,'A strong password is generally:','["the same everywhere", "long, unique and hard to guess", "a pet''s name", "short and memorable"]'::jsonb,1,'Strong passwords resist guessing.','original'),
('127.676.d.11.B',3,'Locking an account after several failed login attempts helps stop:','["slow printers", "screen glare", "brute-force guessing", "power outages"]'::jsonb,2,'Lockouts limit repeated guesses.','original'),
('127.676.d.11.B',4,'A common password policy requires a minimum:','["number of friends", "screen size", "amount of storage", "length and a mix of character types"]'::jsonb,3,'Length and complexity are standard rules.','original'),
('127.676.d.11.C',3,'A brute-force attack tries:','["many possible combinations until one works", "one password only", "passwords from a printer", "only the correct password"]'::jsonb,0,'Brute force tests many options.','original'),
('127.676.d.11.C',4,'A dictionary attack succeeds most often against passwords that are:','["long random strings", "common words or simple variations", "multi-factor protected", "unique passphrases"]'::jsonb,1,'Dictionary attacks try likely words.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_82_v1'
from (values
('127.676.d.11.D',3,'Setting file permissions so only managers can edit a file is an example of:','["screen calibration", "file compression", "access control", "defragmentation"]'::jsonb,2,'Permissions restrict who can act.','original'),
('127.676.d.11.D',4,'A user who should only view a document should be given:','["ownership", "administrator rights", "full control", "read-only permission"]'::jsonb,3,'Least privilege limits actions.','original'),
('127.676.d.12.A',3,'On an operating system, an account with full control of settings and software is a(n):','["administrator account", "service printer", "guest account", "standard account"]'::jsonb,0,'Admins have the highest privileges.','original'),
('127.676.d.12.A',4,'Assigning users to a group such as ''Accounting'' lets an administrator:','["disable all security", "grant permissions to many users at once", "hide the group", "delete every user"]'::jsonb,1,'Groups simplify permission management.','original'),
('127.676.d.12.B',3,'Authentication verifies who you are, while authorization determines:','["when your device was built", "what color your screen is", "what you are allowed to do", "how fast your network is"]'::jsonb,2,'Authorization sets permissions.','original'),
('127.676.d.12.B',4,'Role-based access control assigns permissions according to a user''s:','["home address", "device brand", "favorite color", "job role"]'::jsonb,3,'RBAC ties access to roles.','original'),
('127.676.d.12.C',3,'Which pair is an example of multi-factor authentication?','["a password plus a code sent to a phone", "a username and a user ID", "a password written twice", "two different passwords only"]'::jsonb,0,'It combines different factor types.','original'),
('127.676.d.12.C',4,'A fingerprint scan is an example of something you:','["have", "are", "forget", "know"]'::jsonb,1,'Biometrics are inherence factors.','original'),
('127.676.d.12.D',3,'An air-gapped computer is one that is:','["connected to the most networks", "used only for gaming", "physically isolated from unsecured networks", "always on Wi-Fi"]'::jsonb,2,'Air gaps separate systems from outside networks.','original'),
('127.676.d.12.D',4,'A benefit of air-gapping a critical system is that it:','["guarantees no insider threats", "removes the need for passwords", "makes it faster", "reduces exposure to remote attacks"]'::jsonb,3,'No network path limits remote attacks.','original'),
('127.676.d.12.E',3,'Comparing a downloaded file''s hash to the published hash helps verify its:','["integrity", "color", "download speed", "author''s age"]'::jsonb,0,'Matching hashes mean the file is unchanged.','original'),
('127.676.d.12.E',4,'If a file changes by even one bit, its hash value will:','["stay the same", "change completely", "become shorter", "vanish silently"]'::jsonb,1,'Hashes are sensitive to any change.','original'),
('127.676.d.13.A',3,'Digital forensics is the process of:','["building faster chips", "designing web fonts", "collecting and analyzing digital evidence", "painting screens"]'::jsonb,2,'Forensics investigates digital evidence.','original'),
('127.676.d.13.A',4,'Organizations use digital forensics to:','["avoid keeping any records", "speed up deliveries", "choose office colors", "investigate incidents and support legal action"]'::jsonb,3,'Forensics reveals what happened.','original'),
('127.676.d.13.B',3,'A chain of custody document records:','["who handled evidence and when", "the length of the cable", "the best desktop theme", "the price of the device"]'::jsonb,0,'It tracks evidence handling.','original'),
('127.676.d.13.B',4,'A broken chain of custody can make digital evidence:','["faster to read", "inadmissible or less trustworthy in court", "more valuable", "automatically encrypted"]'::jsonb,1,'Unclear handling undermines evidence.','original'),
('127.676.d.13.C',3,'Which sequence lists the four steps of the forensic process in order?','["examination, reporting, collection, analysis", "reporting, analysis, examination, collection", "collection, examination, analysis, reporting", "analysis, collection, reporting, examination"]'::jsonb,2,'Collect, examine, analyze, then report.','original'),
('127.676.d.13.C',4,'In which forensic step do investigators draw conclusions from the examined data?','["collection", "deletion", "backup", "analysis"]'::jsonb,3,'Analysis interprets findings.','original'),
('127.676.d.13.D',3,'A digital forensics investigation is typically needed after:','["a suspected data breach or policy violation", "a lunch break", "a new wallpaper", "a routine screen cleaning"]'::jsonb,0,'Incidents trigger forensics.','original'),
('127.676.d.13.D',4,'Which situation most likely requires forensics?','["a slow printer", "evidence of employee data theft", "a keyboard that needs cleaning", "a new desktop icon"]'::jsonb,1,'Theft needs evidence collection.','original'),
('127.676.d.13.E',3,'Forensic tools can often recover:','["only new installs", "only paper documents", "deleted files and browsing history", "nothing at all"]'::jsonb,2,'Deleted data can often be recovered.','original'),
('127.676.d.13.E',4,'Metadata such as the time a file was created can help investigators:','["speed up the CPU", "change the owner", "increase file size", "build a timeline of events"]'::jsonb,3,'Timestamps order events.','original'),
('127.676.d.13.F',3,'An event log records:','["system and security events with timestamps", "only battery levels", "only emails sent", "only photos"]'::jsonb,0,'Logs track what happened and when.','original'),
('127.676.d.13.F',4,'Which log entry would most suggest suspicious activity?','["one successful login", "hundreds of failed logins from one address in a minute", "a user logging out", "a scheduled update"]'::jsonb,1,'Rapid failures suggest guessing attacks.','original'),
('127.676.d.14.A',3,'The main purpose of encrypting data is to:','["delete it", "make it larger", "keep it unreadable to unauthorized people", "speed it up"]'::jsonb,2,'Encryption protects confidentiality.','original'),
('127.676.d.14.A',4,'Encryption turns readable data, called plaintext, into unreadable data called:','["hypertext", "metadata", "source code", "ciphertext"]'::jsonb,3,'Ciphertext is encrypted output.','original'),
('127.676.d.14.B',3,'Julius Caesar is said to have protected messages with a:','["shift cipher", "hash table", "firewall", "quantum key"]'::jsonb,0,'The Caesar cipher shifts letters.','original'),
('127.676.d.14.B',4,'During World War II, Germany used the Enigma machine to:','["print newspapers", "encrypt military messages", "cool engines", "dial telephones"]'::jsonb,1,'Enigma was a cipher machine.','original'),
('127.676.d.14.C',3,'With a shift of 3, the letter A becomes:','["E", "B", "D", "C"]'::jsonb,2,'A to B to C to D.','original'),
('127.676.d.14.C',4,'Encrypting the word CAB with a shift of 1 (A becomes B) gives:','["CAB", "BZA", "ECD", "DBC"]'::jsonb,3,'C to D, A to B, B to C.','original'),
('127.676.d.14.D',3,'In public key encryption, which key is shared openly?','["the public key", "the private key", "the screen key", "the home key"]'::jsonb,0,'The public key can be distributed.','original'),
('127.676.d.14.D',4,'A message encrypted with someone''s public key can be decrypted with their:','["public key", "private key", "IP address", "username"]'::jsonb,1,'Only the private key unlocks it.','original'),
('127.676.d.14.E',3,'Symmetric encryption uses:','["no keys", "a public directory", "the same key to encrypt and decrypt", "two different keys"]'::jsonb,2,'One shared secret key.','original'),
('127.676.d.14.E',4,'Compared with symmetric encryption, asymmetric encryption is typically:','["the same speed always", "unable to encrypt", "faster and key-free", "slower but easier for key exchange"]'::jsonb,3,'Asymmetric solves key distribution at a speed cost.','original'),
('127.676.d.15.A',3,'A vulnerability that is exploited before a patch exists is called a:','["zero-day", "blank page", "one-day sale", "dead pixel"]'::jsonb,0,'Zero-days have no fix yet.','original'),
('127.676.d.15.A',4,'Why do unpatched vulnerabilities leave systems open to attack?','["they make hardware louder", "attackers can use the flaw to gain access", "they delete only unused files", "they prevent logins for everyone"]'::jsonb,1,'Known flaws provide an entry point.','original'),
('127.676.d.15.B',3,'Attackers often target people because users are:','["always expert", "unable to click", "easier to trick than strong technical defenses", "never online"]'::jsonb,2,'Humans can be manipulated.','original'),
('127.676.d.15.B',4,'The weakest link in many security systems is the:','["power cable", "monitor stand", "keyboard cover", "human user"]'::jsonb,3,'Human error is the most common cause.','original'),
('127.676.d.15.C',3,'The part of malware that carries out the harmful action is the:','["payload", "logo", "firewall", "update"]'::jsonb,0,'The payload is the damaging action.','original'),
('127.676.d.15.C',4,'Capturing and reading data as it travels across a network is called:','["disk cleanup", "packet sniffing", "file sharing", "port forwarding"]'::jsonb,1,'Sniffers capture network packets.','original'),
('127.676.d.15.D',3,'Code that stays hidden until a trigger, such as a date, then performs harmful actions is a:','["backup", "wallpaper", "logic bomb", "cookie"]'::jsonb,2,'Logic bombs activate on conditions.','original'),
('127.676.d.15.D',4,'An employee misusing their authorized access to steal data is an:','["power failure", "software update", "outside visitor", "insider threat"]'::jsonb,3,'Insiders already hold access.','original'),
('127.676.d.15.E',3,'An attacker secretly intercepting communication between two parties is a:','["man-in-the-middle attack", "reboot", "backup", "calibration"]'::jsonb,0,'The attacker sits between sender and receiver.','original'),
('127.676.d.15.E',4,'A DDoS attack tries to:','["encrypt backups", "overwhelm a service so legitimate users cannot reach it", "patch a server", "fix a website"]'::jsonb,1,'Flooding denies service.','original'),
('127.676.d.15.F',3,'A deceptive email that tricks you into entering your password on a fake site is:','["backing up", "streaming", "phishing", "pinging"]'::jsonb,2,'Phishing impersonates trusted sources.','original'),
('127.676.d.15.F',4,'Phishing through text messages is called:','["vishing", "pharming", "tailgating", "smishing"]'::jsonb,3,'Smishing uses SMS.','original'),
('127.676.d.15.G',3,'Entering SQL commands into a web form to manipulate a database is:','["SQL injection", "packet loss", "port scanning", "screen scraping"]'::jsonb,0,'Unsanitized input lets attackers run queries.','original'),
('127.676.d.15.G',4,'Cross-site scripting (XSS) lets an attacker:','["repair a router", "run malicious scripts in other users'' browsers", "speed up a database", "print remote documents"]'::jsonb,1,'XSS injects scripts into pages.','original'),
('127.676.d.16.A',3,'Connecting to an open public Wi-Fi network is riskier because traffic may be:','["limited to you only", "always encrypted by default", "intercepted by others on the network", "blocked from all sites"]'::jsonb,2,'Open networks expose traffic.','original'),
('127.676.d.16.A',4,'A VPN on public Wi-Fi helps by:','["increasing your data speed always", "removing the password", "hiding the router", "encrypting traffic between your device and the VPN server"]'::jsonb,3,'VPNs protect data in transit.','original'),
('127.676.d.16.B',3,'A supply chain attack compromises a target by:','["tampering with trusted software or hardware from a supplier", "changing the screen", "cleaning the supplier''s office", "slowing all shipping"]'::jsonb,0,'Attackers abuse trusted vendors.','original'),
('127.676.d.16.B',4,'A solution to reduce device vulnerabilities on a network is:','["sharing admin passwords", "network segmentation and regular patching", "disabling all logs", "using default settings"]'::jsonb,1,'Segmentation and patching limit exposure.','original'),
('127.676.d.16.C',3,'HTTPS differs from HTTP mainly because HTTPS:','["blocks all pictures", "uses no ports", "encrypts the data sent between browser and server", "is slower always"]'::jsonb,2,'HTTPS adds TLS encryption.','original'),
('127.676.d.16.C',4,'The padlock icon in a browser address bar indicates the connection uses:','["a faster printer", "a free coupon", "a bigger screen", "TLS encryption"]'::jsonb,3,'Padlocks show an encrypted connection.','original'),
('127.676.d.16.D',3,'An SSID is the:','["name of a wireless network", "serial number of a phone", "password of a router", "speed of a cable"]'::jsonb,0,'The SSID identifies the network.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
